/* @autogenerated */
package net.civeira.phylax.common.security.impl;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.time.Instant;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.security.Actor;

@DisplayName("ActorImpl map conversion")
class ActorImplUnitTest {

  @Test
  @DisplayName("Should round-trip every field through a map")
  void shouldRoundTripThroughMap() {
    // Arrange — a fully populated actor
    Instant at = Instant.parse("2026-01-02T03:04:05Z");
    Actor actor =
        ActorImpl.builder().uid("u").name("n").tenant("t").authenticated(true).roles(List.of("r"))
            .groups(List.of("g")).scopes(List.of("s")).mfa(true).authenticatedAt(at).build();

    // Act — convert to a map and back
    Actor restored = ActorImpl.fromMap(ActorImpl.toMap(actor));

    // Assert — all values survive the conversion
    assertEquals("u", restored.getUid());
    assertEquals("n", restored.getName());
    assertEquals("t", restored.getTenant());
    assertTrue(restored.isAuthenticated());
    assertEquals(List.of("r"), restored.getRoles());
    assertEquals(List.of("g"), restored.getGroups());
    assertEquals(List.of("s"), restored.getScopes());
    assertTrue(restored.isMfa());
    assertEquals(at, restored.getAuthenticatedAt().orElseThrow());
  }

  @Test
  @DisplayName("Should use defaults for missing values")
  void shouldUseDefaultsForMissingValues() {
    // Act — build an actor from an empty map
    Actor restored = ActorImpl.fromMap(Map.of());

    // Assert — every field falls back to its empty value
    assertEquals("", restored.getUid());
    assertFalse(restored.isAuthenticated());
    assertEquals(List.of(), restored.getRoles());
    assertFalse(restored.isMfa());
    assertTrue(restored.getAuthenticatedAt().isEmpty());
  }

  @Test
  @DisplayName("Should parse textual booleans and ignore non list collections")
  void shouldParseTextualValues() {
    // Arrange — values serialized as plain strings
    Map<String, Object> map = new HashMap<>();
    map.put("authenticated", "true");
    map.put("mfa", "no");
    map.put("roles", "admin");

    // Act — build the actor
    Actor restored = ActorImpl.fromMap(map);

    // Assert — strings are parsed and non lists become empty
    assertTrue(restored.isAuthenticated());
    assertFalse(restored.isMfa());
    assertEquals(List.of(), restored.getRoles());
  }
}
